--
-- SWIMS reference data: roles, resources, the role/resource grant matrix, and
-- the service catalogue. Load after `prisma migrate deploy` has built the
-- schema.
--
-- This replaces the old committed pg_dump.sql, which also carried real rows:
-- bcrypt password hashes for the admin and superadmin accounts, and a civil
-- servant's personnel record including national ID numbers. None of that
-- belongs in the repository, and none of it is needed to run the app.
--
-- Contains no personal data. Keep it that way — regenerate by dumping only
-- these four tables:
--
--   pg_dump -a -t '"Role"' -t '"Resources"' -t '"RoleToResource"' \
--           -t services -d <db> > prisma/seed-reference-data.sql
--
-- Usage:
--   psql -d swim_dashboard_dev -f prisma/seed-reference-data.sql
--
-- The permission grid fails closed: a resource with no row denies everyone,
-- including the ministry admin. See SECURITY.md and scripts/seed-permissions.mjs.
--

SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;




